# --- Carregar Bibliotecas ---
library(shiny)
library(bslib) # Para bslib::value_box e ícones
library(dplyr)
library(tidyr)      # Para pivot_longer e unnest
library(purrr)      # Para map_*
library(ggplot2)
library(scales)     # Para formatar eixos e valores (percent)
library(htmltools)
library(readxl)     # Para ler arquivos Excel
library(ggiraph)    # Para gráficos interativos ggplot
library(kableExtra) # Para tabelas estilizadas

# --- Estilos CSS ---
hover_css <- "
  stroke: black;
  stroke-width: 1px;
  r: 8px;
  transition: all 0.3s ease;
"

tooltip_css <- "
  background-color: #2C3E50;
  color: #ECF0F1;
  padding: 10px;
  border-radius: 5px;
  font-family: 'Arial', sans-serif; /* Tooltip pode usar uma fonte segura como Arial */
  font-size: 14px;
  box-shadow: 0px 0px 10px rgba(0,0,0,0.5);
"

# --- Cores Google ---
google_blue <- "#4285F4"
google_red <- "#DB4437"
google_green <- "#0F9D58"
google_yellow <- "#F4B400"
google_palette <- c(google_blue, google_red, google_yellow, google_green, "#AB47BC", "#00ACC1", "#FF7043", "#9E9D24", "#5C6BC0", "#26A69A")

# --- Ordem dos Tipos de Curso ---
ordem_tipo_curso <- c(
  "Qualificação Profissional (FIC)", "Técnico", "Tecnologia", 
  "Licenciatura", "Bacharelado", "Especialização (Lato Sensu)", 
  "Mestrado Profissional"
)

# --- Formas para Tipo de Oferta ---
# Usaremos um conjunto de formas padrão do ggplot2.
# Círculo (16), Quadrado (15), Triângulo (17), Losango (18), Triângulo Invertido (6), Mais (3), Cruz (4)
formas_tipo_oferta_palette <- c(16, 15, 17, 18, 6, 3, 4, 8) 


# --- Carregar Dados Reais ---
# Certifique-se que o nome da unidade consolidada (ex: "IFB") existe nos dados para os indicadores gerais.
NOME_UNIDADE_CONSOLIDADA_IFB <- "IFB" # AJUSTE ESTE NOME SE NECESSÁRIO (ex: "IFB Total", "Reitoria")

tryCatch({
  ef_acad_campus <- read_excel(path = "data/Mapeamento de Cursos PNP.xlsx", sheet = 1) 
  perc_legais <- read_excel("data/Mapeamento de Cursos PNP.xlsx", sheet = 2)
  rap <- read_excel("data/Mapeamento de Cursos PNP.xlsx", sheet = 3) 
  ef_acad_curso <- read_excel(path = "data/Mapeamento de Cursos PNP.xlsx", sheet = 4) 
}, error = function(e) {
  stop(paste("Erro ao carregar arquivos Excel. Verifique se os arquivos estão no diretório 'data' RELATIVO ao app.R e os nomes/planilhas estão corretos:", e$message))
})


# --- Preparar Dados para Plotagem (Indicadores Gerais) ---
perc_legais_pivot <- perc_legais %>%
  select(Ano, Unidade, `Técnicos (IFs) %`, `Formação de Professores (IFs) %`, `Proeja (IFs) %`) %>%
  pivot_longer(
    cols = c(`Técnicos (IFs) %`, `Formação de Professores (IFs) %`, `Proeja (IFs) %`),
    names_to = "Indicador",
    values_to = "Resultado"
  ) %>%
  mutate(
    Meta = case_when(
      Indicador == "Técnicos (IFs) %" ~ 0.50,
      Indicador == "Formação de Professores (IFs) %" ~ 0.20,
      Indicador == "Proeja (IFs) %" ~ 0.10,
      TRUE ~ NA_real_
    ),
    Resultado = as.numeric(Resultado)
  ) %>%
  filter(!is.na(Resultado)) %>%  
  arrange(Unidade, Ano)  

rap_prepared <- rap %>%
  select(Ano, Unidade, Tipo, RAP) %>% 
  rename(Resultado = RAP) %>%
  mutate(
    Indicador = "RAP",
    Meta = 20,  
    Resultado = as.numeric(Resultado),
    Tipo = as.character(Tipo),      
    Tipo = tolower(trimws(Tipo)),   
    Tipo = case_when(               
      Tipo == "distância" ~ "distancia", 
      TRUE ~ Tipo                   
    )
  ) %>%
  filter(!is.na(Resultado), !is.na(Tipo), Tipo %in% c("geral", "presencial", "distancia")) %>% 
  arrange(Unidade, Tipo, Ano)

ef_acad_prepared <- ef_acad_campus %>%
  select(Ano, Unidade, `Eficiência Acadêmica`) %>%  
  rename(Resultado = `Eficiência Acadêmica`) %>%
  mutate(
    Indicador = "Eficiência Acadêmica", 
    Meta = NA_real_,  
    Resultado = as.numeric(Resultado)  
  ) %>%
  filter(!is.na(Resultado)) %>%
  arrange(Unidade, Ano)

conc_ciclo_campus_prepared <- ef_acad_campus %>%
  select(Ano, Unidade, `Conclusão Ciclo %`) %>%  
  rename(Resultado = `Conclusão Ciclo %`) %>%
  mutate(
    Indicador = "Conclusão Ciclo", 
    Meta = NA_real_,
    Resultado = as.numeric(Resultado)  
  ) %>%
  filter(!is.na(Resultado)) %>%
  arrange(Unidade, Ano)

evasao_ciclo_campus_prepared <- ef_acad_campus %>%
  select(Ano, Unidade, `Evasão Ciclo %`) %>%  
  rename(Resultado = `Evasão Ciclo %`) %>%
  mutate(
    Indicador = "Evasão Ciclo", 
    Meta = NA_real_,
    Resultado = as.numeric(Resultado)  
  ) %>%
  filter(!is.na(Resultado)) %>%
  arrange(Unidade, Ano)

retencao_ciclo_campus_prepared <- ef_acad_campus %>%
  select(Ano, Unidade, `Retenção Ciclo %`) %>%  
  rename(Resultado = `Retenção Ciclo %`) %>%
  mutate(
    Indicador = "Retenção Ciclo", 
    Meta = NA_real_,
    Resultado = as.numeric(Resultado)  
  ) %>%
  filter(!is.na(Resultado)) %>%
  arrange(Unidade, Ano)

all_data <- bind_rows(
  perc_legais_pivot,
  rap_prepared, 
  ef_acad_prepared,
  conc_ciclo_campus_prepared,  
  evasao_ciclo_campus_prepared,  
  retencao_ciclo_campus_prepared  
)

# Unidades disponíveis para filtros (inclui a unidade consolidada)
unidades_disponiveis <- sort(unique(all_data$Unidade)) 

# Preparar dados para análise por curso
ef_acad_curso_rede_prepared <- ef_acad_curso %>%
  rename(
    Tipo_Curso = `Tipo de Curso`,
    Tipo_Oferta = `Tipo de Oferta`,
    Modalidade_Ensino = `Modalidade de Ensino`,
    Fonte_Financiamento = `Fonte de Financiamento`,
    Nome_Curso = `Nome do Curso`,
    Eficiencia_Academica = `Eficiência Acadêmica`,
    Conclusao_Ciclo_Perc = `Conclusão Ciclo %`,
    Evasao_Ciclo_Perc = `Evasão Ciclo %`,
    Retencao_Ciclo_Perc = `Retenção Ciclo %`
  ) %>%
  mutate(
    across(c(Eficiencia_Academica, Conclusao_Ciclo_Perc, Evasao_Ciclo_Perc, Retencao_Ciclo_Perc), as.numeric),
    across(c(Instituição, Unidade, Tipo_Curso, Tipo_Oferta, Modalidade_Ensino, Fonte_Financiamento, Nome_Curso), as.character)
  )

ef_acad_curso_ifb_prepared <- ef_acad_curso_rede_prepared %>%
  filter(Instituição == "IFB") 

ifb_campi <- ef_acad_curso_ifb_prepared %>% 
  distinct(Unidade) %>%
  arrange(Unidade) %>%
  pull(Unidade)

anos_disponiveis_curso <- sort(unique(ef_acad_curso_ifb_prepared$Ano), decreasing = TRUE)

# --- Funções Auxiliares ---
calculate_growth <- function(data_subset, indicator_name) {
  if (is.null(data_subset) || nrow(data_subset) == 0 || n_distinct(data_subset$Ano) < 2) {
    return(data.frame(Unidade = character(0),
                      `Crescimento no Período (%)` = character(0),
                      `Crescimento Médio Anual (%)` = character(0),
                      `Crescimento Último Ano (%)` = character(0),
                      check.names = FALSE))
  }
  growth_table <- data_subset %>%
    filter(Indicador == indicator_name) %>% 
    group_by(Unidade) %>% 
    filter(sum(!is.na(Resultado)) >= 2) %>%  
    arrange(Ano) %>%
    summarise(
      n_anos = n_distinct(Ano),
      primeiro_ano_res = first(Resultado[!is.na(Resultado)]),
      ultimo_ano_res = last(Resultado[!is.na(Resultado)]),
      penultimo_ano_res = if (sum(!is.na(Resultado)) >= 2) nth(Resultado[!is.na(Resultado)], n = sum(!is.na(Resultado)) - 1) else NA_real_,
      .groups = 'drop'
    ) %>%
    mutate(
      Crescimento_Periodo = ifelse(primeiro_ano_res != 0 & !is.na(primeiro_ano_res) & !is.na(ultimo_ano_res),
                                   (ultimo_ano_res - primeiro_ano_res) / primeiro_ano_res, NA_real_),
      Crescimento_Medio_Anual = ifelse(n_anos > 1 & primeiro_ano_res != 0 & !is.na(primeiro_ano_res) & !is.na(ultimo_ano_res),
                                       Crescimento_Periodo / (n_anos - 1), NA_real_),
      Crescimento_Ultimo_Ano = ifelse(penultimo_ano_res != 0 & !is.na(penultimo_ano_res) & !is.na(ultimo_ano_res),
                                      (ultimo_ano_res - penultimo_ano_res) / penultimo_ano_res, NA_real_)
    ) %>%
    select(Unidade, Crescimento_Periodo, Crescimento_Medio_Anual, Crescimento_Ultimo_Ano) %>%
    mutate(across(where(is.numeric), ~ scales::percent(., accuracy = 0.01, decimal.mark = ",", big.mark = ".", na_value = "-"))) %>%
    rename(
      `Crescimento no Período (%)` = Crescimento_Periodo,
      `Crescimento Médio Anual (%)` = Crescimento_Medio_Anual,
      `Crescimento Último Ano (%)` = Crescimento_Ultimo_Ano
    )
  return(growth_table)
}

format_pct <- function(value, digits = 1, na_value = "N/A") {
  formatted_value <- ifelse(is.na(value) | !is.numeric(value),
                            na_value,
                            scales::percent(value, accuracy = 1 / (10 ^ digits), decimal.mark = ",", big.mark = ".")
  )
  return(formatted_value)
}

render_growth_table <- function(growth_data) {
  if (is.null(growth_data) || !is.data.frame(growth_data) || nrow(growth_data) == 0) {
    return(tags$p("Nenhuma unidade selecionada com dados suficientes (mínimo 2 anos) para calcular o crescimento.", style = "color: grey; font-style: italic;"))
  }
  growth_data %>%
    kable("html", escape = FALSE, align = 'l') %>%
    kable_styling(bootstrap_options = c("striped", "hover", "condensed", "responsive"),
                  full_width = FALSE, font_size = 12,
                  html_font = "'Arial', sans-serif") %>% # Fallback font
    row_spec(0, background = google_blue, color = "white")
}

# --- Interface do Usuário (UI) ---
