      .kable-table th { white-space: nowrap; }
      .shiny-input-container { margin-bottom: 20px; }
      .filter-row { margin-bottom: 10px; }
      .shiny-input-container .selectize-input { min-height: 38px; }
      .metric-box { 
        background-color: #f8f9fa; border: 1px solid #dee2e6; border-radius: .25rem;
        padding: 15px; margin-bottom: 20px; text-align: center; height: 180px; 
        display: flex; flex-direction: column; justify-content: space-between; 
      }
      .metric-box h5 { 
         margin-top: 0; margin-bottom: 8px; color: #343a40; font-size: 0.9rem; font-weight: bold; 
      }
      .metric-box p { 
        font-size: 1.7rem; font-weight: bold; color: #4285F4; margin-bottom: 8px; 
      }
      .metric-box span { 
        font-size: 0.8em; color: #6c757d; 
      }
      .metric-box .sparkline-plot-container { 
        width: 100%; height: 50px; margin-top: 5px; margin-bottom: 5px;
      }
