        margin-bottom: 20px; /* Adiciona espaço abaixo de cada par de gráficos */
      }
      .row-spacing-tipo-curso { /* Adiciona espaço entre as linhas de gráficos */
        margin-bottom: 25px; 
      }
    "))
  ),
  titlePanel("IFB na PNP"),
  p("Visualização interativa de indicadores selecionados e análise comparativa de cursos do IFB."),
  hr(),
  tabsetPanel(
    id = "main_tabs",
    tabPanel("Painel Resumo", value = "tab_resumo", icon = icon("gauge-high"),
             br(),
             fluidRow( 
               column(3,offset = 1, uiOutput("kpi_box_ef_acad")),
               column(3, uiOutput("kpi_box_rap_geral")),
               column(3, uiOutput("kpi_box_perc_tecnicos"))
             ),
             fluidRow( 
               column(3,offset = 1, uiOutput("kpi_box_perc_form_prof")),
               column(3, uiOutput("kpi_box_perc_proeja")),
               column(6) 
             ),
             fluidRow(
               column(12, 
                      br(), 
                      p(em(paste0("Nota: Os valores exibidos são referentes ao '", NOME_UNIDADE_CONSOLIDADA_IFB, "' para o último ano com dados disponíveis. As metas são institucionais quando aplicável.")), style="font-size:0.9em; color:grey;")
               )
             )
    ),
    tabPanel("Perc. Técnicos", value="tab_perc_tec", icon = icon("person-chalkboard"),
             h4("Percentual Legal para Cursos Técnicos (%)"),
             checkboxGroupInput(inputId = "filter_unidade_tecnicos", label = "Selecione as Unidades:", inline = TRUE, choices = unidades_disponiveis, selected = unidades_disponiveis),
             fluidRow(
               column(width = 7, girafeOutput("plot_perc_tecnicos", height = "500px")), 
               column(width = 5,
                      div(class = "table-title", h5("Análise de Crescimento")), 
                      div(class = "growth-table-container table-responsive", tableOutput("table_perc_tecnicos"))
               )
             )
    ),
    tabPanel("Perc. Form. Professores", value="tab_perc_prof", icon = icon("users-rectangle"),
