             checkboxGroupInput(inputId = "filter_unidade_prof", label = "Selecione as Unidades:", inline = TRUE, choices = unidades_disponiveis, selected = unidades_disponiveis),
             fluidRow(
               column(width = 7, girafeOutput("plot_perc_professores", height = "500px")), 
               column(width = 5,
                      div(class = "table-title", h5("Análise de Crescimento")), 
                      div(class = "growth-table-container table-responsive", tableOutput("table_perc_professores"))
               )
             )
    ),
    tabPanel("Perc. PROEJA", value="tab_proeja", icon = icon("user-graduate"),
             h4("Percentual Legal para PROEJA (%)"),
             checkboxGroupInput(inputId = "filter_unidade_proeja", label = "Selecione as Unidades:", inline = TRUE, choices = unidades_disponiveis, selected = unidades_disponiveis),
             fluidRow(
               column(width = 7, girafeOutput("plot_perc_proeja", height = "500px")), 
               column(width = 5,
                      div(class = "table-title", h5("Análise de Crescimento")), 
                      div(class = "growth-table-container table-responsive", tableOutput("table_perc_proeja"))
               )
             )
    ),
    tabPanel("Relação Aluno/Professor", value="tab_rap", icon = icon("people-group"),
             h4(textOutput("titulo_rap_dinamico")), 
             radioButtons(inputId = "select_tipo_rap", 
                          label = "Selecione a Dimensão do RAP:",
                          choices = c("Geral" = "geral", 
                                      "Presencial" = "presencial", 
                                      "EAD (Distância)" = "distancia"), 
                          selected = "geral", 
                          inline = TRUE),
             checkboxGroupInput(inputId = "filter_unidade_rap", label = "Selecione as Unidades:", inline = TRUE, choices = unidades_disponiveis, selected = unidades_disponiveis),
             fluidRow(
               column(width = 7, girafeOutput("plot_rap", height = "500px")), 
               column(width = 5,
                      div(class = "table-title", h5(textOutput("titulo_crescimento_rap"))), 
                      div(class = "growth-table-container table-responsive", tableOutput("table_rap"))
               )
             )
    ),
    tabPanel("Análise de Eficiência Acadêmica", value="tab_fluxo_acad", icon = icon("chart-line"),
             h4("Indicadores de Eficiência Acadêmica - Por Campus"), 
             tabsetPanel( 
               id = "fluxo_acad_subtabs",
               tabPanel("Eficiência Acadêmica", value="subtab_ef_acad",
                        br(), 
                        checkboxGroupInput(inputId = "filter_unidade_eficiencia", label = "Selecione as Unidades:", inline = TRUE, choices = unidades_disponiveis, selected = unidades_disponiveis),
                        fluidRow(
                          column(width = 7, girafeOutput("plot_ef_academica", height = "500px")), 
                          column(width = 5,
                                 div(class = "table-title", h5("Análise de Crescimento - Eficiência Acadêmica")), 
                                 div(class = "growth-table-container table-responsive", tableOutput("table_ef_academica"))
                          )
                        )
               ),
               tabPanel("Conclusão do Ciclo", value="subtab_conc_ciclo", 
                        br(),
                        checkboxGroupInput(inputId = "filter_unidade_conclusao", label = "Selecione as Unidades:", inline = TRUE, choices = unidades_disponiveis, selected = unidades_disponiveis), 
                        fluidRow(
                          column(width = 7, girafeOutput("plot_conclusao_ciclo", height = "500px")), 
                          column(width = 5,
                                 div(class = "table-title", h5("Análise de Crescimento - Conclusão do Ciclo")),
                                 div(class = "growth-table-container table-responsive", tableOutput("table_conclusao_ciclo")) 
                          )
                        )
               ),
               tabPanel("Evasão do Ciclo", value="subtab_evasao_ciclo", 
                        br(),
                        checkboxGroupInput(inputId = "filter_unidade_evasao", label = "Selecione as Unidades:", inline = TRUE, choices = unidades_disponiveis, selected = unidades_disponiveis), 
                        fluidRow(
                          column(width = 7, girafeOutput("plot_evasao_ciclo", height = "500px")), 
                          column(width = 5,
                                 div(class = "table-title", h5("Análise de Crescimento - Evasão do Ciclo")),
                                 div(class = "growth-table-container table-responsive", tableOutput("table_evasao_ciclo")) 
                          )
                        )
               ),
               tabPanel("Retenção do Ciclo", value="subtab_retencao_ciclo", 
                        br(),
                        checkboxGroupInput(inputId = "filter_unidade_retencao", label = "Selecione as Unidades:", inline = TRUE, choices = unidades_disponiveis, selected = unidades_disponiveis), 
                        fluidRow(
                          column(width = 7, girafeOutput("plot_retencao_ciclo", height = "500px")), 
                          column(width = 5,
                                 div(class = "table-title", h5("Análise de Crescimento - Retenção do Ciclo")),
                                 div(class = "growth-table-container table-responsive", tableOutput("table_retencao_ciclo")) 
