             hr(),
             fluidRow(class="row-spacing-tipo-curso", 
                      column(6, 
                             div(class="plot-title-tipo-curso", "Eficiência Acadêmica"),
                             div(class="girafe-tipo-curso-container", girafeOutput("plot_ef_acad_tipo_curso"))
                      ),
                      column(6, 
                             div(class="plot-title-tipo-curso", "Conclusão do Ciclo (%)"),
                             div(class="girafe-tipo-curso-container", girafeOutput("plot_conc_ciclo_tipo_curso"))
                      )
             ),
             fluidRow(class="row-spacing-tipo-curso",
                      column(6, 
                             div(class="plot-title-tipo-curso", "Evasão do Ciclo (%)"),
                             div(class="girafe-tipo-curso-container", girafeOutput("plot_evasao_ciclo_tipo_curso"))
                      ),
                      column(6, 
                             div(class="plot-title-tipo-curso", "Retenção do Ciclo (%)"),
                             div(class="girafe-tipo-curso-container", girafeOutput("plot_retencao_ciclo_tipo_curso"))
                      )
             )
    ),
    tabPanel("Análise da Eficiência Acadêmica por Curso", value = "tab_analise_curso", icon = icon("microscope"),
             h4("Análise Comparativa de Cursos do IFB"),
             p("Selecione Ano, Campus, Tipo de Curso, Modalidade, Oferta, Fonte de Financiamento e Nome do Curso para visualizar a performance em comparação com a Rede Federal e outras ofertas do mesmo curso."),
             fluidRow( class = "filter-row", column(4, selectInput("select_ano_curso", "Ano:", choices = anos_disponiveis_curso, selected = if(length(anos_disponiveis_curso)>0) max(anos_disponiveis_curso) else NULL))),
             fluidRow( class = "filter-row", 
                       column(4, selectInput("select_ifb_campus", "Campus IFB:", choices = ifb_campi)), 
                       column(4, selectInput("select_tipo_curso", "Tipo de Curso (Programa/Eixo):", choices = NULL)), 
                       column(4, selectInput("select_modalidade", "Modalidade de Ensino:", choices = NULL))
             ),
             fluidRow( class = "filter-row", 
                       column(4, selectInput("select_tipo_oferta", "Tipo de Oferta:", choices = NULL)), 
                       column(4, selectInput("select_fonte_financiamento", "Fonte de Financiamento:", choices = NULL)),
                       column(4, selectInput("select_curso_ifb", "Nome do Curso:", choices = NULL))
