# --- Lógica do Servidor ---
server <- function(input, output, session) {
  
  # --- Lógica para o Painel Resumo (Dashboard) ---
  dados_ifb_agregados <- reactive({
    req(all_data, NOME_UNIDADE_CONSOLIDADA_IFB) 
    
    get_kpi_data <- function(indicador_nome, tipo_rap_especifico = NULL) {
      data_filtrada <- all_data %>%
        filter(Indicador == indicador_nome, Unidade == NOME_UNIDADE_CONSOLIDADA_IFB)
      
      if (!is.null(tipo_rap_especifico)) { 
        data_filtrada <- data_filtrada %>% filter(Tipo == tipo_rap_especifico)
      }
      
      historico_data <- data_filtrada %>%
        select(Ano, Resultado) %>%
        filter(!is.na(Resultado)) %>%
        rename(Valor = Resultado) %>%
        arrange(Ano) 
      
      ultimo_valor <- if(nrow(historico_data) > 0) {
        historico_data %>% filter(Ano == max(Ano, na.rm = TRUE)) %>% pull(Valor)
      } else { NA_real_ }
      if(length(ultimo_valor) == 0) ultimo_valor <- NA_real_
      
      meta_valor <- unique(data_filtrada$Meta[!is.na(data_filtrada$Meta)])
      if(length(meta_valor) == 0) meta_valor <- NA_real_ else meta_valor <- meta_valor[1]
      
      ultimo_ano_registrado <- if(nrow(historico_data) > 0) max(historico_data$Ano, na.rm = TRUE) else NA_integer_
      
      return(list(valor = ultimo_valor, historico = historico_data, meta = meta_valor, ultimo_ano_kpi = ultimo_ano_registrado))
    }
    
    list(
      ef_acad_ifb = get_kpi_data("Eficiência Acadêmica"),
      rap_ifb = get_kpi_data("RAP", tipo_rap_especifico = "geral"),
      perc_tec_ifb = get_kpi_data("Técnicos (IFs) %"),
      perc_prof_ifb = get_kpi_data("Formação de Professores (IFs) %"),
      perc_proeja_ifb = get_kpi_data("Proeja (IFs) %") 
    )
  })
  
  create_sparkline <- function(data_hist, y_col = "Valor", meta_val = NA, cor_linha = google_blue, cor_meta = google_red, y_format_func = waiver()) {
    if (is.null(data_hist) || nrow(data_hist) < 1 || all(is.na(data_hist[[y_col]]))) { 
      return(ggplot() + theme_void() + annotate("text", x=0.5, y=0.5, label="Dados insuf.", size=2.5, color="grey50"))
    }
    
    data_hist_plot <- data_hist %>% filter(!is.na(.data[[y_col]]))
    if (nrow(data_hist_plot) == 0) {
      return(ggplot() + theme_void() + annotate("text", x=0.5, y=0.5, label="Dados insuf.", size=2.5, color="grey50"))
    }
    
    p <- ggplot(data_hist_plot, aes(x = Ano, y = .data[[y_col]]))
    
    if (nrow(data_hist_plot) >= 2) { 
      p <- p + geom_line(color = cor_linha, linewidth = 0.8)
    }
    p <- p + geom_point(data = data_hist_plot %>% filter(Ano == max(Ano)), color = cor_linha, size = 1.2) +
      theme_void() +
      theme(plot.margin = margin(1,1,1,1), aspect.ratio = 0.3) 
    
    if (!is.na(meta_val) && is.numeric(meta_val)) {
      p <- p + geom_hline(yintercept = meta_val, linetype = "dashed", color = cor_meta, linewidth = 0.6)
    }
    
    if (identical(y_format_func, scales::percent)) {
      min_val_data <- if(nrow(data_hist_plot) > 0) min(data_hist_plot[[y_col]], na.rm = TRUE) else NA_real_
      max_val_data <- if(nrow(data_hist_plot) > 0) max(data_hist_plot[[y_col]], na.rm = TRUE) else NA_real_
      
      all_vals_for_ylim <- c(min_val_data, max_val_data)
      if(!is.na(meta_val)) all_vals_for_ylim <- c(all_vals_for_ylim, meta_val)
      all_vals_for_ylim <- all_vals_for_ylim[!is.na(all_vals_for_ylim)]
      
      if(length(all_vals_for_ylim) > 0){
        min_val_plot <- min(all_vals_for_ylim)
        max_val_plot <- max(all_vals_for_ylim)
        buffer <- (max_val_plot - min_val_plot) * 0.1 
        if (buffer == 0 || !is.finite(buffer)) buffer <- 0.01 
        p <- p + coord_cartesian(ylim = c(min_val_plot - buffer, max_val_plot + buffer))
      }
    }
    return(p)
  }
  
  output$kpi_box_ef_acad_spark <- renderPlot({
    req(dados_ifb_agregados()$ef_acad_ifb$historico)
    create_sparkline(dados_ifb_agregados()$ef_acad_ifb$historico, y_col = "Valor", y_format_func = scales::percent)
