  create_indicator_plot_girafe <- function(data_subset, title_suffix, y_label, y_format = waiver(), show_meta = TRUE) {
    if (is.null(data_subset) || nrow(data_subset) == 0 || all(is.na(data_subset$Resultado))) { 
      p_empty <- ggplot() + 
        annotate("text", x = 0.5, y = 0.5, 
                 label = paste("Nenhuma unidade selecionada ou dados indisponíveis para", title_suffix), 
                 hjust = 0.5, size = 5, color = "grey50") + 
        theme_void()
      return(girafe(ggobj = p_empty, height_svg = 7, width_svg = 10)) 
    } 
    num_unidades <- n_distinct(data_subset$Unidade)
    current_palette <- rep(google_palette, length.out = num_unidades)
    
    tooltip_format_internal <- function(value_tt) {
      is_percent_format <- inherits(y_format, "function") && 
        (identical(deparse(body(y_format)), deparse(body(scales::percent_format(accuracy = 0.1)))) || 
           identical(deparse(body(y_format)), deparse(body(scales::percent))))
      
      if (is_percent_format) {
        return(scales::percent(value_tt, accuracy = 0.01, decimal.mark = ",", big.mark = "."))
      } else {
        return(format(round(value_tt, 2), nsmall = 2, decimal.mark = ",", big.mark = "."))
      }
    }
    
    p <- ggplot(data_subset, aes(x = Ano, y = Resultado, color = Unidade, group = Unidade, 
                                 tooltip = paste("Unidade:", Unidade, "<br>Ano:", Ano, "<br>", y_label, ":", tooltip_format_internal(Resultado)), 
                                 data_id = paste(Unidade, Ano, sep = "_"))) + 
      geom_line_interactive(linewidth = 0.8, na.rm = TRUE) + 
      geom_point_interactive(size = 2.5, na.rm = TRUE) + 
      scale_x_continuous(breaks = unique(data_subset$Ano)) + 
      labs(x = "Ano", y = y_label, color = "Unidade") + 
      theme_minimal() + # Removido base_family
      theme(axis.title = element_text(size = 12), 
            axis.text = element_text(size = 10), 
            legend.title = element_text(size = 11, face = "bold"), 
            legend.text = element_text(size = 10), 
            legend.position = "bottom") + 
      scale_color_manual(values = current_palette)
    
    meta_value <- NA
    if (show_meta && "Meta" %in% names(data_subset) && any(!is.na(data_subset$Meta))) { 
      meta_values_unique <- unique(data_subset$Meta[!is.na(data_subset$Meta)])
      if(length(meta_values_unique) == 1) { 
        meta_value <- meta_values_unique
        p <- p + geom_hline_interactive(aes(yintercept = meta_value, 
                                            tooltip = paste("Meta:", tooltip_format_internal(meta_value)), 
                                            data_id = paste("Meta", title_suffix, sep="_")), 
                                        linetype = "dashed", color = google_red, linewidth = 0.7) 
      } else if (length(meta_values_unique) > 1) { 
        # warning(paste("Multiple distinct Meta values found for indicator:", title_suffix, ". Meta line not drawn.")) 
      } 
    }
    
    y_max_val <- tryCatch({ 
      max_val <- max(c(data_subset$Resultado, if(!is.na(meta_value) && is.numeric(meta_value)) meta_value else -Inf), na.rm = TRUE)
      if(is.finite(max_val)) max_val * 1.1 else 1 
    }, warning = function(w) { 
      if(all(is.na(data_subset$Resultado)) && (is.na(meta_value) || !is.numeric(meta_value))) return(1)
      if(all(is.na(data_subset$Resultado))) return(if(is.na(meta_value) || !is.numeric(meta_value)) 1 else meta_value * 1.1)
      return(max(data_subset$Resultado, na.rm = TRUE) * 1.1) 
    })
    if (!is.finite(y_max_val) || y_max_val == 0) y_max_val <- 1
    y_min_val <- 0 
    if(y_label == "RAP" && any(data_subset$Resultado > 0, na.rm=TRUE)) {
      y_min_val <- min(0, min(data_subset$Resultado, na.rm=TRUE) * 0.9, na.rm=TRUE) 
    }
    
    
    y_limits <- c(y_min_val, y_max_val)
    
    if (!identical(y_format, waiver()) && is.function(y_format)) { 
      p <- p + scale_y_continuous(labels = y_format, limits = y_limits, oob = scales::squish) 
    } else { 
      p <- p + scale_y_continuous(limits = y_limits, oob = scales::squish, labels = scales::number_format(accuracy = 0.01, decimal.mark = ",", big.mark = "."))
    }
    
    girafe(ggobj = p, 
           options = list(opts_hover(css = hover_css), 
                          opts_tooltip(css = tooltip_css, use_fill = TRUE), 
                          opts_hover_inv(css = "opacity:0.3;"), 
                          opts_sizing(rescale = TRUE, width = 1)), 
           height_svg = 7, width_svg = 10) 
  }
  
  output$plot_perc_tecnicos <- renderGirafe({ req(input$filter_unidade_tecnicos); data_subset <- all_data %>% filter(Indicador == "Técnicos (IFs) %", Unidade %in% input$filter_unidade_tecnicos); create_indicator_plot_girafe(data_subset, "Perc. Técnicos", "Percentual", y_format = scales::percent_format(accuracy = 0.1, decimal.mark = ",", big.mark = "."), show_meta = TRUE) })
