  output$plot_perc_proeja <- renderGirafe({ req(input$filter_unidade_proeja); data_subset <- all_data %>% filter(Indicador == "Proeja (IFs) %", Unidade %in% input$filter_unidade_proeja); create_indicator_plot_girafe(data_subset, "Perc. PROEJA", "Percentual", y_format = scales::percent_format(accuracy = 0.1, decimal.mark = ",", big.mark = "."), show_meta = TRUE) })
  output$table_perc_proeja <- function() { req(input$filter_unidade_proeja); data_filtered <- all_data %>% filter(Indicador == "Proeja (IFs) %", Unidade %in% input$filter_unidade_proeja); growth_data <- calculate_growth(data_filtered, "Proeja (IFs) %"); render_growth_table(growth_data) }
  
  map_tipo_rap_label <- c("geral" = "Geral", "presencial" = "Presencial", "distancia" = "EAD (Distância)")
  
  output$titulo_rap_dinamico <- renderText({
    req(input$select_tipo_rap)
    tipo_label_amigavel <- map_tipo_rap_label[input$select_tipo_rap]
    if (is.na(tipo_label_amigavel)) tipo_label_amigavel <- tools::toTitleCase(input$select_tipo_rap) 
    paste("Relação Aluno/Professor (RAP) -", tipo_label_amigavel)
  })
  
  output$titulo_crescimento_rap <- renderText({
    req(input$select_tipo_rap)
    tipo_label_amigavel <- map_tipo_rap_label[input$select_tipo_rap]
    if (is.na(tipo_label_amigavel)) tipo_label_amigavel <- tools::toTitleCase(input$select_tipo_rap) 
    paste("Análise de Crescimento - RAP", tipo_label_amigavel)
  })
  
  output$plot_rap <- renderGirafe({ 
    req(input$filter_unidade_rap, input$select_tipo_rap) 
    data_subset <- all_data %>% 
      filter(
        Indicador == "RAP", 
        Unidade %in% input$filter_unidade_rap,
        Tipo == input$select_tipo_rap 
      )
    tipo_label_amigavel <- map_tipo_rap_label[input$select_tipo_rap]
