  # CORRIGIDO: Função de plotagem para a nova aba
  create_scatter_plot_tipo_curso <- function(data_plot, metric_col_name, y_label_plot) {
    req(data_plot)
    
    data_metric_specific <- data_plot %>%
      select(Nome_Curso, Tipo_Curso, Tipo_Oferta, Metrica = all_of(metric_col_name)) %>% 
      filter(!is.na(Metrica), !is.na(Tipo_Curso), !is.na(Tipo_Oferta)) 
    
    if (nrow(data_metric_specific) == 0) {
      p_empty <- ggplot() + 
        annotate("text", x = 0.5, y = 0.5, label = "Dados insuficientes ou N/A para esta métrica e filtros.", 
                 hjust = 0.5, size = 4, color = "grey50") + 
        theme_void()
      return(girafe(ggobj = p_empty, height_svg = 5, width_svg = 10))
    }
    
    # Converter para character ANTES de ggplot para compatibilidade com shinylive
    data_metric_specific <- data_metric_specific %>%
      mutate(
        Tipo_Curso = as.character(Tipo_Curso),
        Tipo_Oferta = as.character(Tipo_Oferta)
      )
    
    # Obter os tipos de curso presentes nos dados e ordená-los conforme a ordem global
    tipos_de_curso_presentes <- intersect(ordem_tipo_curso, unique(data_metric_specific$Tipo_Curso))
    num_tipos_curso <- length(tipos_de_curso_presentes)
    
    paleta_tipo_curso <- if (num_tipos_curso <= length(google_palette)) {
      google_palette[1:num_tipos_curso]
    } else {
      additional_colors <- scales::hue_pal()(num_tipos_curso - length(google_palette))
      c(google_palette, additional_colors)
    }
    names(paleta_tipo_curso) <- tipos_de_curso_presentes 
    
    # Formas para Tipo de Oferta
    tipos_de_oferta_presentes <- sort(unique(data_metric_specific$Tipo_Oferta))
    num_tipos_oferta <- length(tipos_de_oferta_presentes)
    paleta_formas_oferta <- rep(formas_tipo_oferta_palette, length.out = num_tipos_oferta)
    names(paleta_formas_oferta) <- tipos_de_oferta_presentes
    
    p <- ggplot(data_metric_specific, aes(x = Tipo_Curso, y = Metrica, 
                                          color = Tipo_Curso, 
                                          shape = Tipo_Oferta, 
                                          tooltip = paste0("Curso: ", Nome_Curso, 
                                                           "<br>Tipo de Curso: ", Tipo_Curso,
                                                           "<br>Tipo de Oferta: ", Tipo_Oferta,
                                                           "<br>", y_label_plot, ": ", format_pct(Metrica)),
                                          data_id = paste(Nome_Curso, Tipo_Oferta, sep="_"))) + 
      geom_jitter_interactive(width = 0.25, alpha = 0.8, size = 3.5, na.rm = TRUE) + 
      scale_color_manual(values = paleta_tipo_curso, name = "Tipo de Curso", limits = names(paleta_tipo_curso), drop = FALSE) + 
      scale_shape_manual(values = paleta_formas_oferta, name = "Tipo de Oferta", limits = names(paleta_formas_oferta), drop = FALSE) + 
      scale_x_discrete(limits = tipos_de_curso_presentes) + # Forçar ordem do eixo X
      scale_y_continuous(labels = scales::percent_format(accuracy = 1)) +
      labs(x = "Tipo de Curso", y = y_label_plot, color = "Tipo de Curso", shape = "Tipo de Oferta") +
      theme_minimal() + # Removido base_family
      theme(
        axis.text.x = element_text(angle = 45, hjust = 1, size = rel(0.85)), 
        axis.title = element_text(size = rel(0.95)),
        legend.position = "bottom",
        legend.box = "vertical",
        legend.title = element_text(face = "bold", size = rel(0.9)),
        legend.text = element_text(size = rel(0.8)),
        plot.margin = margin(t = 10, r = 20, b = 10, l = 10) 
      )
    
    girafe(
      ggobj = p,
      options = list(
        opts_hover(css = hover_css),
        opts_tooltip(css = tooltip_css, use_fill = TRUE, opacity = 0.9),
        opts_selection(type = "none"),
        opts_sizing(rescale = TRUE, width = 1)
      ), 
      height_svg = 6 
    )
  }
  
