    validate(need(nrow(data_comp.func) > 0, "Não foram encontrados dados de comparação na Rede para este curso com as características selecionadas."), 
             need(!is.null(averages.func) && nrow(averages.func) > 0 && !all(is.na(unlist(averages.func))), "Médias da rede não puderam ser calculadas para este curso específico."))
    
    data_comp.func <- data_comp.func %>% arrange(desc(Eficiencia_Academica))
    
    data_kable <- data_comp.func %>%
      # Adiciona a coluna de Ranking aqui
      mutate(
        Ranking = row_number(),
        Instituição_cell = if_else(Is_IFB_Selected, cell_spec(Instituição, bold = TRUE, escape = FALSE, color = "white", background = google_blue), cell_spec(Instituição, escape = FALSE)),
        Unidade_cell = if_else(Is_IFB_Selected, cell_spec(Unidade, bold = TRUE, escape = FALSE, color = "white", background = google_blue), cell_spec(Unidade, escape = FALSE)),
        Eficiencia_Academica_cell = cell_spec(format_pct(Eficiencia_Academica), background = case_when(is.na(Eficiencia_Academica) | is.na(averages.func$Avg_Eficiencia) ~ "#bdc3c7", Eficiencia_Academica >= averages.func$Avg_Eficiencia ~ google_green, TRUE ~ google_red), color = "white", escape = FALSE),
        Conclusao_Ciclo_Perc_cell = cell_spec(format_pct(Conclusao_Ciclo_Perc), background = case_when(is.na(Conclusao_Ciclo_Perc) | is.na(averages.func$Avg_Conclusao) ~ "#bdc3c7", Conclusao_Ciclo_Perc >= averages.func$Avg_Conclusao ~ google_green, TRUE ~ google_red), color = "white", escape = FALSE),
        Evasao_Ciclo_Perc_cell = cell_spec(format_pct(Evasao_Ciclo_Perc), background = case_when(is.na(Evasao_Ciclo_Perc) | is.na(averages.func$Avg_Evasao) ~ "#bdc3c7", Evasao_Ciclo_Perc <= averages.func$Avg_Evasao ~ google_green, TRUE ~ google_red), color = "white", escape = FALSE),
        Retencao_Ciclo_Perc_cell = cell_spec(format_pct(Retencao_Ciclo_Perc), background = case_when(is.na(Retencao_Ciclo_Perc) | is.na(averages.func$Avg_Retencao) ~ "#bdc3c7", Retencao_Ciclo_Perc >= averages.func$Avg_Retencao ~ google_green, TRUE ~ google_red), color = "white", escape = FALSE)
      ) %>%
      # Seleciona a nova coluna de Ranking para ser exibida
      select(Ranking, Instituição_cell, Unidade_cell, Eficiencia_Academica_cell, Conclusao_Ciclo_Perc_cell, Evasao_Ciclo_Perc_cell, Retencao_Ciclo_Perc_cell) %>%
      # Renomeia as colunas, incluindo a de Ranking
      rename(Ranking = Ranking, Instituição = Instituição_cell, Unidade = Unidade_cell,
             `Efic. Acad.(%)` = Eficiencia_Academica_cell, `Conclusão(%)` = Conclusao_Ciclo_Perc_cell,
             `Evasão(%)` = Evasao_Ciclo_Perc_cell, `Retenção(%)` = Retencao_Ciclo_Perc_cell)
    
    kable(data_kable, format = "html", escape = FALSE, align = c('c', 'l', 'l', 'r', 'r', 'r', 'r'), table.attr = "class='table kable-table'") %>%
      kable_styling(bootstrap_options = c("striped", "hover", "condensed", "responsive"),
                    full_width = FALSE, font_size = 11, position = "center", html_font = "'Arial', sans-serif") %>%
      row_spec(0, background = google_blue, color = "white")
  }
  
  output$plot_comparacao_distribuicao_girafe <- renderGirafe({
    data_comp <- dados_comparacao_rede_curso_especifico() 
    data_ifb_instancia <- dados_curso_ifb_selecionado_instancia()
    averages_curso_especifico <- averages_rede_curso_especifico() 
    
    validate(
      need(nrow(data_comp) > 1, "Dados insuficientes na rede para gerar gráfico de distribuição para este curso específico (mínimo 2 pontos totais)."), 
      need(nrow(data_ifb_instancia) > 0, "Dados da instância IFB selecionada não encontrados para marcar no gráfico de distribuição."), 
      need(!is.null(averages_curso_especifico) && nrow(averages_curso_especifico) > 0 && !all(is.na(unlist(averages_curso_especifico))), "Médias da rede (curso específico) não puderam ser calculadas.")
    )
    
    data_comp_long_raw <- data_comp %>%
      select(Eficiencia_Academica, Conclusao_Ciclo_Perc, Evasao_Ciclo_Perc, Retencao_Ciclo_Perc) %>%
      pivot_longer(cols = everything(), names_to = "Metrica_Orig", values_to = "Valor") %>%
      filter(!is.na(Valor)) %>%
      mutate(Metrica = case_when(
        Metrica_Orig == "Eficiencia_Academica"   ~ "Eficiência Acadêmica",
        Metrica_Orig == "Conclusao_Ciclo_Perc" ~ "Conclusão Ciclo (%)",
        Metrica_Orig == "Evasao_Ciclo_Perc"    ~ "Evasão Ciclo (%)",
        Metrica_Orig == "Retencao_Ciclo_Perc"  ~ "Retenção Ciclo (%)",
        TRUE ~ Metrica_Orig
      )) %>%
      select(Metrica, Valor)
    
    data_comp_long <- data_comp_long_raw %>%
      group_by(Metrica) %>%
      filter(n() >= 2) %>% 
      ungroup()
    
    if (nrow(data_comp_long) == 0) {
      p_empty <- ggplot() + 
        annotate("text", x = 0.5, y = 0.5, 
                 label = "Não há métricas com dados suficientes\n(mínimo 2 pontos por métrica) na rede\npara plotar a distribuição.", 
                 hjust = 0.5, size = 4, color = "grey50") + 
        theme_void()
      return(girafe(ggobj = p_empty, height_svg = 5, width_svg = 10))
    }
    
    ifb_vals <- data_ifb_instancia %>% select(Eficiencia_Academica, Conclusao_Ciclo_Perc, Evasao_Ciclo_Perc, Retencao_Ciclo_Perc)
    avg_vals_curso_especifico <- averages_rede_curso_especifico() %>% select(Avg_Eficiencia, Avg_Conclusao, Avg_Evasao, Avg_Retencao)
    
    comparison_lines <- tibble(
      Metrica_Orig_Map = c("Eficiencia_Academica", "Conclusao_Ciclo_Perc", "Evasao_Ciclo_Perc", "Retencao_Ciclo_Perc"),
      Metrica = c("Eficiência Acadêmica", "Conclusão Ciclo (%)", "Evasão Ciclo (%)", "Retenção Ciclo (%)"),
      Value_IFB = c(ifb_vals$Eficiencia_Academica, ifb_vals$Conclusao_Ciclo_Perc, ifb_vals$Evasao_Ciclo_Perc, ifb_vals$Retencao_Ciclo_Perc),
      Value_Avg = c(avg_vals_curso_especifico$Avg_Eficiencia, avg_vals_curso_especifico$Avg_Conclusao, avg_vals_curso_especifico$Avg_Evasao, avg_vals_curso_especifico$Avg_Retencao)
    ) %>%
      pivot_longer(cols = c(Value_IFB, Value_Avg), names_to = "Type_Raw", values_to = "Value") %>%
      mutate(Type = factor(ifelse(Type_Raw == "Value_IFB", "IFB Campus Selecionado", "Média Rede (Curso Espec.)"),
                           levels = c("IFB Campus Selecionado", "Média Rede (Curso Espec.)"))) %>%
      filter(!is.na(Value)) %>%
      filter(Metrica %in% unique(data_comp_long$Metrica)) %>% 
      mutate(tooltip = paste0(Type, ": ", format_pct(Value))) %>%
      select(Metrica, Value, Type, tooltip)
    
    p <- ggplot() +
      geom_density_interactive(
        data = data_comp_long, 
        aes(x = Valor, tooltip = sprintf("Densidade para %s", Metrica), data_id = Metrica),
        fill = google_blue, alpha = 0.5, color = google_blue, na.rm = TRUE
      )
    
    if(nrow(comparison_lines) > 0 && any(!is.na(comparison_lines$Value))) {
      p <- p + geom_vline_interactive(
        data = comparison_lines, 
        aes(xintercept = Value, color = Type, linetype = Type, tooltip = tooltip, data_id = paste(Metrica, Type)),
        linewidth = 1, na.rm = TRUE
      )
    }
    
    p <- p + 
      scale_x_continuous(labels = scales::percent_format(accuracy = 1)) +
      scale_color_manual(name = "Referência", values = c("IFB Campus Selecionado" = google_red, "Média Rede (Curso Espec.)" = "black"), drop = FALSE) +
      scale_linetype_manual(name = "Referência", values = c("IFB Campus Selecionado" = "dashed", "Média Rede (Curso Espec.)" = "dotted"), drop = FALSE) +
      facet_wrap(~Metrica, scales = "free") +
      labs(title = NULL, x = "Valor do Indicador", y = "Densidade") +
      theme_minimal() + # Removido base_family
      theme(
        strip.text = element_text(face = "bold", size = rel(1.0)),
        axis.text = element_text(size = rel(0.9)),
        axis.title = element_text(size = rel(0.9)),
        legend.position = "bottom",
        legend.title = element_text(face = "bold", size = rel(0.9)),
        legend.text = element_text(size = rel(0.85)),
        plot.margin = margin(t = 5, r = 10, b = 5, l = 5)
      )
    
    girafe(ggobj = p,
           options = list(
             opts_hover(css = hover_css),
             opts_tooltip(css = tooltip_css, use_fill = TRUE, opacity = 0.9),
             opts_hover_inv(css = "opacity:0.2;"),
             opts_selection(type = "none"),
             opts_sizing(rescale = TRUE, width = 1)
           ),
           height_svg = 5, width_svg = 10)
  })
  
  create_scatter_plot_curso_girafe <- function(metric_col, data_plot_points, avg_val_curso_especifico, y_label_plot, metric_name_tooltip, campus_ifb_label) {
    validate(need(nrow(data_plot_points) > 0, paste("Não há ocorrências do curso selecionado na Rede Federal para os filtros especificados para a métrica:", y_label_plot)))
    data_plot_points_filtered <- data_plot_points %>% filter(!is.na(.data[[metric_col]]))
    validate(need(nrow(data_plot_points_filtered) > 0, paste("Todas as ocorrências do curso selecionado na Rede Federal para os filtros especificados possuem valor N/A para a métrica:", y_label_plot)), 
             need(!is.na(avg_val_curso_especifico), paste("Média da Rede Federal (para o curso específico) não disponível para a métrica:", y_label_plot)))
    distinct_ofertas <- length(unique(data_plot_points_filtered$Tipo_Oferta))
    shape_values <- rep(c(16, 17, 15, 18, 1, 2, 0, 5, 6), length.out = distinct_ofertas)
    p_scatter <- ggplot(data_plot_points_filtered, aes(x = reorder(paste(Nome_Curso, " (", Instituição, "-", Unidade, ")"), -.data[[metric_col]]), y = .data[[metric_col]], 
                                                       shape = Tipo_Oferta, color = as.factor(Is_IFB_Selected), 
                                                       tooltip = paste0("Instituição: ", Instituição, "<br>Unidade: ", Unidade, "<br>Curso: ", Nome_Curso, "<br>Tipo de Oferta: ", 
                                                                        Tipo_Oferta, "<br>", metric_name_tooltip, ": ", 
                                                                        format_pct(.data[[metric_col]])), data_id = paste(Instituição, Unidade, Nome_Curso, Tipo_Oferta, sep="_"))) + 
      geom_point_interactive(size = 3.5, alpha = 0.8, na.rm = TRUE) + 
      geom_hline_interactive(yintercept = avg_val_curso_especifico, linetype = "dashed", 
                             color = google_red, linewidth = 1, tooltip = paste("Média Rede (Curso Específico & Ano):", format_pct(avg_val_curso_especifico)), 
                             data_id = paste0("media_rede_curso_especifico_", metric_col)) + scale_y_continuous(labels = scales::percent_format(accuracy = 1)) + 
      scale_shape_manual(name = "Tipo de Oferta:", values = shape_values) + scale_color_manual(name = "Destaque:", values = c("TRUE" = google_green, "FALSE" = google_blue), 
                                                                                               labels = c("TRUE" = paste("IFB -", campus_ifb_label), "FALSE" = "Outras Instituições da Rede")) + 
      labs(x = "Curso (Instituição-Unidade) (ordenado pela métrica)", y = y_label_plot) + 
      theme_minimal() + # Removido base_family
      theme(
        axis.text.x = element_text(angle = 20, hjust = 1, size = rel(0.75)), 
        axis.title.x = element_text(margin = margin(t = 20, b = 15), size = rel(0.8)), 
        axis.title.y = element_text(size = rel(0.8), margin = margin(r = 15)), 
        legend.position = "right",
        legend.box = "vertical",
        legend.title = element_text(face = "bold", size = rel(0.8)), 
        legend.text = element_text(size = rel(0.75)), 
        legend.box.margin = margin(t = 15, unit = "pt"), 
        plot.title = element_text(hjust = 0.5, face = "bold", color = google_blue, size = rel(0.9)), 
        plot.margin = unit(c(1, 1, 3, 1.5), "cm") 
      )
    girafe(ggobj = p_scatter, 
           options = list(
             opts_hover(css = hover_css),
             opts_tooltip(css = tooltip_css, use_fill = TRUE, opacity = 0.9),
             opts_hover_inv(css = "opacity:0.3;"), 
             opts_selection(type = "none"), 
             opts_sizing(rescale = FALSE, width = 1)
           ),
           width_svg = 17, 
           height_svg = 5 
    )
  }
  
